<script setup>
import {ref,watch} from 'vue'
import {api,formatTime} from '../lib/api'
const props=defineProps({studentId:String,classId:String,subject:String}),source=ref('all'),data=ref(null),error=ref(''),loading=ref(false);let sequence=0
async function load(){const current=++sequence;loading.value=true;try{const result=await api('/learning-stats?'+new URLSearchParams({source:source.value,...(props.studentId?{studentId:props.studentId}:{}),...(props.classId?{classId:props.classId}:{}),...(props.subject?{subject:props.subject}:{})}));if(current===sequence){data.value=result;error.value=''}}catch(e){if(current===sequence)error.value=e.message}finally{if(current===sequence)loading.value=false}}
watch(()=>[source.value,props.studentId,props.classId,props.subject],load,{immediate:true})
</script>
<template><section class="panel source-stats"><div class="workshop-heading"><h2>출처별 학습 실적</h2><div class="source-filter" aria-label="학습 실적 출처"><button v-for="v in [{id:'all',name:'전체'},{id:'official',name:'공식'},{id:'student',name:'학생 제작'}]" :key="v.id" :class="{selected:source===v.id}" @click="source=v.id">{{v.name}}</button><button class="text-button" :disabled="loading" @click="load">↻ 갱신</button></div></div><p v-if="error" role="alert">{{error}}</p><template v-if="data"><div class="stats"><span>풀이 수<b>{{data.selected.solved}}회</b></span><span>정답률<b>{{data.selected.accuracy}}%</b></span><span>오답 수<b>{{data.selected.wrong}}회</b></span></div><div class="source-time"><span>전체 {{formatTime(data.time.totalSeconds)}}</span><span>공식 학습 {{formatTime(data.time.officialSeconds)}}</span><span>학생 문제 {{formatTime(data.time.studentSeconds)}}</span></div><p class="chart-note">풀이 수는 제출된 답안 수이며 재도전을 포함합니다. 정답률은 제출 답안 중 정답 비율입니다. 공식 진도율은 공식 문제만 계산합니다.</p></template></section></template>
